B.b6P=s(["Quiero a mi mam\xe1.","T\xf4i y\xeau m\u1eb9."],t.s)
B.af5=s(["\xa1Hola, maestra!","Em ch\xe0o c\xf4 \u1ea1!"],t.s)
B.avx=s(["El mar es azul.","Bi\u1ec3n xanh."],t.s)
